use std::fs
use std::collections::HashMap

fn num(s: string) -> int {
    s.parse::<int>().unwrap_or(0)
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut acc: HashMap<string, int> = HashMap::new()
    for line in text.lines() {
        let p: Vec<string> = line.split_whitespace().collect()
        if p.len() == 0 {
            continue
        }
        let cmd = p[0]
        if cmd == "open" && p.len() >= 3 {
            let amt = num(p[2])
            if amt < 0 {
                println("error: invalid amount")
            } else if acc.contains_key(p[1]) {
                println("error: duplicate account")
            } else {
                acc.insert(p[1], amt)
                println("ok")
            }
        } else if (cmd == "deposit" || cmd == "withdraw") && p.len() >= 3 {
            let amt = num(p[2])
            if amt <= 0 {
                println("error: invalid amount")
            } else if !acc.contains_key(p[1]) {
                println("error: unknown account ${p[1]}")
            } else {
                let bal = acc.get(p[1]).unwrap_or(0)
                if cmd == "deposit" {
                    acc.insert(p[1], bal + amt)
                    println("ok")
                } else if amt > bal {
                    println("error: insufficient funds")
                } else {
                    acc.insert(p[1], bal - amt)
                    println("ok")
                }
            }
        } else if cmd == "transfer" && p.len() >= 4 {
            let amt = num(p[3])
            if amt <= 0 {
                println("error: invalid amount")
            } else if !acc.contains_key(p[1]) {
                println("error: unknown account ${p[1]}")
            } else if !acc.contains_key(p[2]) {
                println("error: unknown account ${p[2]}")
            } else if p[1] == p[2] {
                println("error: same account")
            } else {
                let a = acc.get(p[1]).unwrap_or(0)
                let b = acc.get(p[2]).unwrap_or(0)
                if amt > a {
                    println("error: insufficient funds")
                } else {
                    acc.insert(p[1], a - amt)
                    acc.insert(p[2], b + amt)
                    println("ok")
                }
            }
        } else if cmd == "balance" && p.len() >= 2 {
            if !acc.contains_key(p[1]) {
                println("error: unknown account ${p[1]}")
            } else {
                println("${acc.get(p[1]).unwrap_or(0)}")
            }
        }
    }
    let mut keys: Vec<string> = []
    for k in acc.keys() {
        keys.push(k)
    }
    keys.sort()
    for k in keys {
        println("${k} ${acc.get(k).unwrap_or(0)}")
    }
}

